import{E as e,d as t,l as n}from"./runtime-core.esm-bundler-tCF-J6l5.js";import{t as r}from"./app-D7E9GCrC.js";var i=JSON.parse(`{"path":"/%E5%90%8E%E7%AB%AF%E5%BC%80%E5%8F%91/Rust/MoNode/03_%E6%89%A7%E8%A1%8C%E8%AE%B0%E5%BD%95.html","title":"MoNode · 03 执行记录","lang":"zh-CN","frontmatter":{"title":"MoNode · 03 执行记录","icon":"fa6-solid:code","order":3,"category":["MoNode"],"tag":["MoNode","Embassy","编译错误","嵌入式"]},"git":{"createdTime":1777281196000,"updatedTime":1777281196000,"contributors":[{"name":"jackie.liu","username":"","email":"moklgy@foxmail.com","commits":1}]},"readingTime":{"minutes":8.84,"words":2652},"filePathRelative":"后端开发/Rust/MoNode/03_执行记录.md"}`),a={name:`03_执行记录.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="monode-·-执行记录" tabindex="-1"><a class="header-anchor" href="#monode-·-执行记录"><span>MoNode · 执行记录</span></a></h1><blockquote><p><strong>角色</strong>：【Dev】主导<br><strong>记录</strong>：Embassy 特有编译障碍 + 架构决策（ADR）+ 关键实现过程</p></blockquote><hr><h2 id="一、编译错误记录" tabindex="-1"><a class="header-anchor" href="#一、编译错误记录"><span>一、编译错误记录</span></a></h2><h3 id="e1-embassy-executor-task-不允许泛型参数" tabindex="-1"><a class="header-anchor" href="#e1-embassy-executor-task-不允许泛型参数"><span>E1：<code>#[embassy_executor::task]</code> 不允许泛型参数</span></a></h3><p><strong>错误代码</strong>：</p><div class="language-rust line-numbers-mode" data-highlighter="shiki" data-ext="rust" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-rust"><span class="line"><span style="color:#7F848E;font-style:italic;">// 尝试用泛型 I2C trait 抽象，方便单元测试注入 mock</span></span>
<span class="line"><span style="color:#ABB2BF;">#[embassy_executor::task]</span></span>
<span class="line"><span style="color:#C678DD;">async</span><span style="color:#C678DD;"> fn</span><span style="color:#61AFEF;"> sensor_loop</span><span style="color:#ABB2BF;">&lt;</span><span style="color:#E5C07B;">I</span><span style="color:#ABB2BF;">&gt;(</span><span style="color:#E06C75;">i2c</span><span style="color:#ABB2BF;">: </span><span style="color:#E5C07B;">I</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">where</span></span>
<span class="line"><span style="color:#E5C07B;">    I</span><span style="color:#ABB2BF;">: </span><span style="color:#E5C07B;">embedded_hal_async</span><span style="color:#ABB2BF;">::</span><span style="color:#E5C07B;">i2c</span><span style="color:#ABB2BF;">::</span><span style="color:#E5C07B;">I2c</span><span style="color:#ABB2BF;"> + &#39;</span><span style="color:#E5C07B;">static</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">{</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    // ...</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>编译错误</strong>：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>error: task functions must not be generic</span></span>
<span class="line"><span>  --&gt; src/main.rs:15:1</span></span>
<span class="line"><span>   |</span></span>
<span class="line"><span>15 | async fn sensor_loop&lt;I&gt;(i2c: I)</span></span>
<span class="line"><span>   | ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^</span></span>
<span class="line"><span>   |</span></span>
<span class="line"><span>   = note: this error originates in the attribute macro \`embassy_executor::task\`</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>原因分析</strong>：</p><p>Embassy executor 在编译期为每个 task 分配一个 <code>TaskStorage&lt;F&gt;</code> 结构体，其大小必须在编译期确定。泛型参数 <code>I</code> 导致 Future 大小随类型变化，破坏静态分配的前提。</p><p><strong>修复方案</strong>：使用 HAL 提供的具体类型替代 trait bound：</p><div class="language-rust line-numbers-mode" data-highlighter="shiki" data-ext="rust" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-rust"><span class="line"><span style="color:#7F848E;font-style:italic;">// ✅ 使用具体的 embassy-rp 类型</span></span>
<span class="line"><span style="color:#ABB2BF;">#[embassy_executor::task]</span></span>
<span class="line"><span style="color:#C678DD;">async</span><span style="color:#C678DD;"> fn</span><span style="color:#61AFEF;"> sensor_loop</span><span style="color:#ABB2BF;">(</span></span>
<span class="line"><span style="color:#E06C75;">    i2c</span><span style="color:#ABB2BF;">: </span><span style="color:#E5C07B;">embassy_rp</span><span style="color:#ABB2BF;">::</span><span style="color:#E5C07B;">i2c</span><span style="color:#ABB2BF;">::</span><span style="color:#E5C07B;">I2c</span><span style="color:#ABB2BF;">&lt;&#39;</span><span style="color:#E5C07B;">static</span><span style="color:#ABB2BF;">, </span><span style="color:#E5C07B;">I2C0</span><span style="color:#ABB2BF;">, </span><span style="color:#E06C75;">embassy_rp</span><span style="color:#ABB2BF;">::</span><span style="color:#E06C75;">i2c</span><span style="color:#ABB2BF;">::</span><span style="color:#E5C07B;">Async</span><span style="color:#ABB2BF;">&gt;,</span></span>
<span class="line"><span style="color:#E06C75;">    uart_tx</span><span style="color:#ABB2BF;">: </span><span style="color:#E5C07B;">embassy_rp</span><span style="color:#ABB2BF;">::</span><span style="color:#E5C07B;">uart</span><span style="color:#ABB2BF;">::</span><span style="color:#E5C07B;">UartTx</span><span style="color:#ABB2BF;">&lt;&#39;</span><span style="color:#E5C07B;">static</span><span style="color:#ABB2BF;">, </span><span style="color:#E5C07B;">UART0</span><span style="color:#ABB2BF;">, </span><span style="color:#E06C75;">embassy_rp</span><span style="color:#ABB2BF;">::</span><span style="color:#E06C75;">uart</span><span style="color:#ABB2BF;">::</span><span style="color:#E5C07B;">Blocking</span><span style="color:#ABB2BF;">&gt;,</span></span>
<span class="line"><span style="color:#ABB2BF;">) -&gt; </span><span style="color:#56B6C2;">!</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    // ...</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>对 C# 开发者的类比</strong>：</p><p>这相当于 C# IL2CPP AOT 编译时，泛型方法必须在发布前被具体类型实例化。Embassy task 宏是编译期 AOT，不支持运行时泛型分发。</p><hr><h3 id="e2-no-std-中不能使用-format-宏" tabindex="-1"><a class="header-anchor" href="#e2-no-std-中不能使用-format-宏"><span>E2：no_std 中不能使用 <code>format!</code> 宏</span></a></h3><p><strong>错误代码</strong>：</p><div class="language-rust line-numbers-mode" data-highlighter="shiki" data-ext="rust" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-rust"><span class="line"><span style="color:#7F848E;font-style:italic;">// 想用 format! 生成 JSON 字符串</span></span>
<span class="line"><span style="color:#C678DD;">let</span><span style="color:#E06C75;"> json</span><span style="color:#56B6C2;"> =</span><span style="color:#61AFEF;"> format!</span><span style="color:#ABB2BF;">(</span></span>
<span class="line"><span style="color:#98C379;">    r#&quot;{{&quot;ts&quot;:{},&quot;temp&quot;:{:.1},&quot;hum&quot;:{:.1}}}&quot;#</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#E06C75;">    ts_ms</span><span style="color:#ABB2BF;">, </span><span style="color:#E06C75;">temp</span><span style="color:#ABB2BF;">, </span><span style="color:#E06C75;">hum</span></span>
<span class="line"><span style="color:#ABB2BF;">);</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>编译错误</strong>：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>error[E0433]: failed to resolve: use of undeclared crate or module \`alloc\`</span></span>
<span class="line"><span>  --&gt; src/reporter/uart.rs:12:15</span></span>
<span class="line"><span>   |</span></span>
<span class="line"><span>12 |     let json = format!(...);</span></span>
<span class="line"><span>   |                ^^^^^^ use of undeclared crate or module \`alloc\`</span></span>
<span class="line"><span></span></span>
<span class="line"><span>error[E0463]: can&#39;t find crate for \`std\`</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>两个子问题</strong>：</p><ol><li><code>format!</code> 需要 <code>alloc::string::String</code>，而 <code>#![no_std]</code> 禁用了 <code>alloc</code></li><li>即使加 <code>extern crate alloc</code>，RP2040 也没有默认的 global allocator（违反 AC4）</li></ol><p><strong>修复方案</strong>：使用 <code>heapless::String&lt;N&gt;</code> + <code>core::fmt::Write</code> + <code>write!</code>：</p><div class="language-rust line-numbers-mode" data-highlighter="shiki" data-ext="rust" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-rust"><span class="line"><span style="color:#C678DD;">use</span><span style="color:#E5C07B;"> core</span><span style="color:#ABB2BF;">::</span><span style="color:#E5C07B;">fmt</span><span style="color:#ABB2BF;">::</span><span style="color:#E5C07B;">Write</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">use</span><span style="color:#E5C07B;"> heapless</span><span style="color:#ABB2BF;">::</span><span style="color:#E5C07B;">String</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">fn</span><span style="color:#61AFEF;"> format_json</span><span style="color:#ABB2BF;">(</span><span style="color:#E06C75;">ts_ms</span><span style="color:#ABB2BF;">: </span><span style="color:#E5C07B;">u64</span><span style="color:#ABB2BF;">, </span><span style="color:#E06C75;">reading</span><span style="color:#ABB2BF;">: &amp;</span><span style="color:#E5C07B;">SensorReading</span><span style="color:#ABB2BF;">) -&gt; </span><span style="color:#E5C07B;">String</span><span style="color:#ABB2BF;">&lt;</span><span style="color:#E06C75;">128</span><span style="color:#ABB2BF;">&gt; {</span></span>
<span class="line"><span style="color:#C678DD;">    let</span><span style="color:#C678DD;"> mut</span><span style="color:#E06C75;"> buf</span><span style="color:#ABB2BF;">: </span><span style="color:#E5C07B;">String</span><span style="color:#ABB2BF;">&lt;</span><span style="color:#E06C75;">128</span><span style="color:#ABB2BF;">&gt; </span><span style="color:#56B6C2;">=</span><span style="color:#E5C07B;"> String</span><span style="color:#ABB2BF;">::</span><span style="color:#61AFEF;">new</span><span style="color:#ABB2BF;">();</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    // 整数 × 10 格式化，避免浮点（Cortex-M0+ 无 FPU）</span></span>
<span class="line"><span style="color:#C678DD;">    let</span><span style="color:#E06C75;"> t</span><span style="color:#56B6C2;"> =</span><span style="color:#E06C75;"> reading</span><span style="color:#ABB2BF;">.temperature_decidegrees;</span></span>
<span class="line"><span style="color:#C678DD;">    let</span><span style="color:#E06C75;"> sign</span><span style="color:#56B6C2;"> =</span><span style="color:#C678DD;"> if</span><span style="color:#E06C75;"> t</span><span style="color:#56B6C2;"> &lt;</span><span style="color:#D19A66;"> 0</span><span style="color:#ABB2BF;"> { </span><span style="color:#98C379;">&quot;-&quot;</span><span style="color:#ABB2BF;"> } </span><span style="color:#C678DD;">else</span><span style="color:#ABB2BF;"> { </span><span style="color:#98C379;">&quot;&quot;</span><span style="color:#ABB2BF;"> };</span></span>
<span class="line"><span style="color:#C678DD;">    let</span><span style="color:#E06C75;"> t_abs</span><span style="color:#56B6C2;"> =</span><span style="color:#E06C75;"> t</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">unsigned_abs</span><span style="color:#ABB2BF;">();</span></span>
<span class="line"><span style="color:#C678DD;">    let</span><span style="color:#E06C75;"> h</span><span style="color:#56B6C2;"> =</span><span style="color:#E06C75;"> reading</span><span style="color:#ABB2BF;">.humidity_decipercent;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    // write! 宏对 no_std heapless::String 有效</span></span>
<span class="line"><span style="color:#61AFEF;">    write!</span><span style="color:#ABB2BF;">(</span></span>
<span class="line"><span style="color:#E06C75;">        buf</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#98C379;">        &quot;{{\\&quot;ts\\&quot;:{},\\&quot;temp\\&quot;:{}{}.{},\\&quot;hum\\&quot;:{}.{}}}&quot;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#E06C75;">        ts_ms</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#E06C75;">        sign</span><span style="color:#ABB2BF;">, </span><span style="color:#E06C75;">t_abs</span><span style="color:#ABB2BF;"> / </span><span style="color:#D19A66;">10</span><span style="color:#ABB2BF;">, </span><span style="color:#E06C75;">t_abs</span><span style="color:#ABB2BF;"> % </span><span style="color:#D19A66;">10</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#E06C75;">        h</span><span style="color:#ABB2BF;"> / </span><span style="color:#D19A66;">10</span><span style="color:#ABB2BF;">, </span><span style="color:#E06C75;">h</span><span style="color:#ABB2BF;"> % </span><span style="color:#D19A66;">10</span></span>
<span class="line"><span style="color:#ABB2BF;">    )</span></span>
<span class="line"><span style="color:#ABB2BF;">    .</span><span style="color:#61AFEF;">ok</span><span style="color:#ABB2BF;">(); </span><span style="color:#7F848E;font-style:italic;">// heapless::String 满了返回 Err，此处 ignore（128 字节足够）</span></span>
<span class="line"></span>
<span class="line"><span style="color:#E06C75;">    buf</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>关键认知</strong>：</p><ul><li><code>write!</code> 宏来自 <code>core::fmt</code>，在 <code>no_std</code> 中可用</li><li><code>heapless::String&lt;N&gt;</code> 实现了 <code>core::fmt::Write</code>，因此 <code>write!</code> 能写入</li><li><code>.ok()</code> 处理容量溢出（<code>String&lt;128&gt;</code> 容纳 JSON 绰绰有余）</li></ul><hr><h3 id="e3-embassy-rp-的-time-driver-feature-缺失" tabindex="-1"><a class="header-anchor" href="#e3-embassy-rp-的-time-driver-feature-缺失"><span>E3：<code>embassy-rp</code> 的 <code>time-driver</code> feature 缺失</span></a></h3><p><strong>错误代码</strong>（Cargo.toml 漏了关键 feature）：</p><div class="language-toml line-numbers-mode" data-highlighter="shiki" data-ext="toml" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-toml"><span class="line"><span style="color:#ABB2BF;">[</span><span style="color:#61AFEF;">dependencies</span><span style="color:#ABB2BF;">]</span></span>
<span class="line"><span style="color:#E06C75;">embassy-rp</span><span style="color:#ABB2BF;"> = { </span><span style="color:#E06C75;">version</span><span style="color:#ABB2BF;"> = </span><span style="color:#98C379;">&quot;0.9.0&quot;</span><span style="color:#ABB2BF;">, </span><span style="color:#E06C75;">features</span><span style="color:#ABB2BF;"> = [</span><span style="color:#98C379;">&quot;defmt&quot;</span><span style="color:#ABB2BF;">] }  </span><span style="color:#7F848E;font-style:italic;"># 缺少 time-driver</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>编译错误</strong>：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>error[E0433]: failed to resolve: use of undeclared crate or module \`embassy_time\`</span></span>
<span class="line"><span>  --&gt; src/main.rs:5:5</span></span>
<span class="line"><span>   |</span></span>
<span class="line"><span>5  |     embassy_time::Timer::after_millis(80).await;</span></span>
<span class="line"><span>   |                   ^^^^^ use of undeclared crate or module \`embassy_time\`</span></span>
<span class="line"><span></span></span>
<span class="line"><span>note: \`embassy-time\` requires a time driver, enable one of:</span></span>
<span class="line"><span>      - \`embassy-rp/time-driver\`</span></span>
<span class="line"><span>      - \`embassy-stm32/time-driver-*\`</span></span>
<span class="line"><span>      - \`embassy-nrf/time-driver-*\`</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>原因</strong>：<code>embassy-time</code> 是抽象层，需要平台的 <code>time-driver</code> feature 提供底层计时支持（RP2040 使用 Timer peripheral）。</p><p><strong>修复</strong>：</p><div class="language-toml line-numbers-mode" data-highlighter="shiki" data-ext="toml" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-toml"><span class="line"><span style="color:#E06C75;">embassy-rp</span><span style="color:#ABB2BF;"> = { </span><span style="color:#E06C75;">version</span><span style="color:#ABB2BF;"> = </span><span style="color:#98C379;">&quot;0.9.0&quot;</span><span style="color:#ABB2BF;">, </span><span style="color:#E06C75;">features</span><span style="color:#ABB2BF;"> = [</span></span>
<span class="line"><span style="color:#98C379;">    &quot;defmt&quot;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#98C379;">    &quot;time-driver&quot;</span><span style="color:#ABB2BF;">,          </span><span style="color:#FFFFFF;">← 必须！</span></span>
<span class="line"><span style="color:#98C379;">    &quot;critical-section-impl&quot;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">] }</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h3 id="e4-task-参数需要-static-生命周期" tabindex="-1"><a class="header-anchor" href="#e4-task-参数需要-static-生命周期"><span>E4：task 参数需要 <code>&#39;static</code> 生命周期</span></a></h3><p><strong>错误代码</strong>：</p><div class="language-rust line-numbers-mode" data-highlighter="shiki" data-ext="rust" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-rust"><span class="line"><span style="color:#ABB2BF;">#[embassy_executor::main]</span></span>
<span class="line"><span style="color:#C678DD;">async</span><span style="color:#C678DD;"> fn</span><span style="color:#61AFEF;"> main</span><span style="color:#ABB2BF;">(</span><span style="color:#E06C75;">spawner</span><span style="color:#ABB2BF;">: </span><span style="color:#E5C07B;">Spawner</span><span style="color:#ABB2BF;">) {</span></span>
<span class="line"><span style="color:#C678DD;">    let</span><span style="color:#E06C75;"> p</span><span style="color:#56B6C2;"> =</span><span style="color:#E5C07B;"> embassy_rp</span><span style="color:#ABB2BF;">::</span><span style="color:#61AFEF;">init</span><span style="color:#ABB2BF;">(</span><span style="color:#E5C07B;">Default</span><span style="color:#ABB2BF;">::</span><span style="color:#61AFEF;">default</span><span style="color:#ABB2BF;">());</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    // 局部变量 —— 生命周期 &lt; &#39;static</span></span>
<span class="line"><span style="color:#C678DD;">    let</span><span style="color:#E06C75;"> i2c</span><span style="color:#56B6C2;"> =</span><span style="color:#E5C07B;"> i2c</span><span style="color:#ABB2BF;">::</span><span style="color:#E5C07B;">I2c</span><span style="color:#ABB2BF;">::</span><span style="color:#61AFEF;">new_async</span><span style="color:#ABB2BF;">(</span><span style="color:#E06C75;">p</span><span style="color:#ABB2BF;">.</span><span style="color:#E5C07B;">I2C0</span><span style="color:#ABB2BF;">, </span><span style="color:#E06C75;">p</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">PIN_5</span><span style="color:#ABB2BF;">, </span><span style="color:#E06C75;">p</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">PIN_4</span><span style="color:#ABB2BF;">, </span><span style="color:#E5C07B;">Irqs</span><span style="color:#ABB2BF;">, </span><span style="color:#E5C07B;">I2cConfig</span><span style="color:#ABB2BF;">::</span><span style="color:#61AFEF;">default</span><span style="color:#ABB2BF;">());</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    // 试图传递局部变量给 task</span></span>
<span class="line"><span style="color:#E06C75;">    spawner</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">spawn</span><span style="color:#ABB2BF;">(</span><span style="color:#61AFEF;">sensor_loop</span><span style="color:#ABB2BF;">(</span><span style="color:#E06C75;">i2c</span><span style="color:#ABB2BF;">)).</span><span style="color:#61AFEF;">unwrap</span><span style="color:#ABB2BF;">();</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    // &#39;main 函数返回后 i2c 被释放，但 task 还在运行 → 悬空引用！</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>编译错误</strong>：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>error[E0597]: \`i2c\` does not live long enough</span></span>
<span class="line"><span>   |</span></span>
<span class="line"><span>   | spawner.spawn(sensor_loop(i2c)).unwrap();</span></span>
<span class="line"><span>   |                            ^^^ borrowed value does not live long enough</span></span>
<span class="line"><span>   |</span></span>
<span class="line"><span>   = note: task requires \`&#39;static\` lifetime</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>修复</strong>：RP2040 的 <code>embassy_rp::init()</code> 返回的外设 handle 具有 <code>&#39;static</code> 生命周期（外设寄存器地址永不失效），直接<strong>移动</strong>到 task，不通过引用：</p><div class="language-rust line-numbers-mode" data-highlighter="shiki" data-ext="rust" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-rust"><span class="line"><span style="color:#7F848E;font-style:italic;">// ✅ Peripherals 移动（不是借用）给 task，类型自动推断为 &#39;static</span></span>
<span class="line"><span style="color:#C678DD;">let</span><span style="color:#E06C75;"> i2c</span><span style="color:#ABB2BF;">: </span><span style="color:#E5C07B;">I2c</span><span style="color:#ABB2BF;">&lt;&#39;</span><span style="color:#E5C07B;">static</span><span style="color:#ABB2BF;">, </span><span style="color:#E5C07B;">I2C0</span><span style="color:#ABB2BF;">, </span><span style="color:#E5C07B;">Async</span><span style="color:#ABB2BF;">&gt; </span><span style="color:#56B6C2;">=</span><span style="color:#E5C07B;"> I2c</span><span style="color:#ABB2BF;">::</span><span style="color:#61AFEF;">new_async</span><span style="color:#ABB2BF;">(</span></span>
<span class="line"><span style="color:#E06C75;">    p</span><span style="color:#ABB2BF;">.</span><span style="color:#E5C07B;">I2C0</span><span style="color:#ABB2BF;">, </span><span style="color:#E06C75;">p</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">PIN_5</span><span style="color:#ABB2BF;">, </span><span style="color:#E06C75;">p</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">PIN_4</span><span style="color:#ABB2BF;">, </span><span style="color:#E5C07B;">Irqs</span><span style="color:#ABB2BF;">, </span><span style="color:#E5C07B;">I2cConfig</span><span style="color:#ABB2BF;">::</span><span style="color:#61AFEF;">default</span><span style="color:#ABB2BF;">()</span></span>
<span class="line"><span style="color:#ABB2BF;">);</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">// i2c 的生命周期绑定到 I2C0 peripheral，后者是 RP2040 静态地址 → &#39;static ✓</span></span>
<span class="line"><span style="color:#E06C75;">spawner</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">spawn</span><span style="color:#ABB2BF;">(</span><span style="color:#61AFEF;">sensor_loop</span><span style="color:#ABB2BF;">(</span><span style="color:#E06C75;">i2c</span><span style="color:#ABB2BF;">, </span><span style="color:#E06C75;">uart_tx</span><span style="color:#ABB2BF;">)).</span><span style="color:#61AFEF;">unwrap</span><span style="color:#ABB2BF;">();</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">// main() 此后可以 loop {}，其生命周期不影响已移入 task 的外设</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>对 C# 开发者的类比</strong>：</p><p>这相当于将 <code>IDisposable</code> 对象的所有权转给一个后台 <code>Task</code>。Rust 的借用检查器在编译期保证没有悬空引用——C# 靠 GC，Rust 靠所有权规则。</p><hr><h3 id="e5-i2c-错误类型不匹配-不能直接用" tabindex="-1"><a class="header-anchor" href="#e5-i2c-错误类型不匹配-不能直接用"><span>E5：I²C 错误类型不匹配，<code>?</code> 不能直接用</span></a></h3><p><strong>错误代码</strong>：</p><div class="language-rust line-numbers-mode" data-highlighter="shiki" data-ext="rust" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-rust"><span class="line"><span style="color:#C678DD;">pub</span><span style="color:#C678DD;"> async</span><span style="color:#C678DD;"> fn</span><span style="color:#61AFEF;"> init</span><span style="color:#ABB2BF;">(&amp;</span><span style="color:#C678DD;">mut</span><span style="color:#E5C07B;"> self</span><span style="color:#ABB2BF;">, </span><span style="color:#E06C75;">i2c</span><span style="color:#ABB2BF;">: &amp;</span><span style="color:#C678DD;">mut</span><span style="color:#E5C07B;"> I2c</span><span style="color:#ABB2BF;">&lt;&#39;</span><span style="color:#E5C07B;">_</span><span style="color:#ABB2BF;">, </span><span style="color:#E5C07B;">I2C0</span><span style="color:#ABB2BF;">, </span><span style="color:#E5C07B;">Async</span><span style="color:#ABB2BF;">&gt;) -&gt; </span><span style="color:#E5C07B;">Result</span><span style="color:#ABB2BF;">&lt;(), </span><span style="color:#E5C07B;">SensorError</span><span style="color:#ABB2BF;">&gt; {</span></span>
<span class="line"><span style="color:#E06C75;">    i2c</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">write</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">AHT20_ADDR</span><span style="color:#ABB2BF;">, &amp;</span><span style="color:#D19A66;">CMD_INIT</span><span style="color:#ABB2BF;">).</span><span style="color:#C678DD;">await</span><span style="color:#ABB2BF;">?;  </span><span style="color:#7F848E;font-style:italic;">// ❌ 类型不匹配</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    // ...</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>编译错误</strong>：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>error[E0277]: \`?\` couldn&#39;t convert the error to \`SensorError\`</span></span>
<span class="line"><span>  --&gt; src/sensor/aht20.rs:42:47</span></span>
<span class="line"><span>   |</span></span>
<span class="line"><span>42 |     i2c.write(AHT20_ADDR, &amp;CMD_INIT).await?;</span></span>
<span class="line"><span>   |                                            ^ the trait \`From&lt;embassy_rp::i2c::Error&gt;\`</span></span>
<span class="line"><span>   |                                              is not implemented for \`SensorError\`</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>原因</strong>：<code>?</code> 运算符自动调用 <code>From::from(e)</code> 转换错误类型，而 <code>SensorError</code> 没有为 <code>embassy_rp::i2c::Error</code> 实现 <code>From</code>。</p><p><strong>修复方案</strong>：使用 <code>.map_err(|_| SensorError::I2c)?</code>：</p><div class="language-rust line-numbers-mode" data-highlighter="shiki" data-ext="rust" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-rust"><span class="line"><span style="color:#7F848E;font-style:italic;">// ✅ 显式映射错误类型</span></span>
<span class="line"><span style="color:#E06C75;">i2c</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">write</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">AHT20_ADDR</span><span style="color:#ABB2BF;">, &amp;</span><span style="color:#D19A66;">CMD_INIT</span><span style="color:#ABB2BF;">).</span><span style="color:#C678DD;">await</span></span>
<span class="line"><span style="color:#ABB2BF;">    .</span><span style="color:#61AFEF;">map_err</span><span style="color:#ABB2BF;">(</span><span style="color:#56B6C2;">|</span><span style="color:#E06C75;">_</span><span style="color:#56B6C2;">|</span><span style="color:#E5C07B;"> SensorError</span><span style="color:#ABB2BF;">::</span><span style="color:#E5C07B;">I2c</span><span style="color:#ABB2BF;">)?;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>为什么不实现 <code>From&lt;i2c::Error&gt;</code>？</strong></p><p>在 no_std 环境中，<code>i2c::Error</code> 是泛型类型 <code>ErrorKind</code>（不同 HAL 实现各自的 I²C 错误）。在嵌入式驱动中，通常只关心&quot;成功 / I²C 失败&quot;的粗粒度结果，详细 I²C 错误通过 <code>defmt::error!</code> 记录，不需要在错误链中传播。</p><hr><h3 id="e6-bind-interrupts-宏放置位置错误" tabindex="-1"><a class="header-anchor" href="#e6-bind-interrupts-宏放置位置错误"><span>E6：<code>bind_interrupts!</code> 宏放置位置错误</span></a></h3><p><strong>错误代码（放在 <code>sensor/aht20.rs</code> 中）</strong>：</p><div class="language-rust line-numbers-mode" data-highlighter="shiki" data-ext="rust" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-rust"><span class="line"><span style="color:#7F848E;font-style:italic;">// ❌ bind_interrupts! 必须在使用外设的 crate 根或 main.rs 中</span></span>
<span class="line"><span style="color:#61AFEF;">bind_interrupts!</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">struct</span><span style="color:#E5C07B;"> Irqs</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#E5C07B;">    I2C0_IRQ</span><span style="color:#ABB2BF;"> =&gt; </span><span style="color:#E5C07B;">i2c</span><span style="color:#ABB2BF;">::</span><span style="color:#E5C07B;">InterruptHandler</span><span style="color:#ABB2BF;">&lt;</span><span style="color:#E5C07B;">I2C0</span><span style="color:#ABB2BF;">&gt;;</span></span>
<span class="line"><span style="color:#ABB2BF;">});</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>错误</strong>：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>error[E0412]: cannot find type \`Irqs\` in this scope</span></span>
<span class="line"><span>  --&gt; src/main.rs:25:43</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>修复</strong>：<code>bind_interrupts!</code> 必须在 <code>main.rs</code> 或 <code>lib.rs</code> 中定义，因为它会生成一个实现 <code>Handler</code> trait 的结构体，需要在整个 crate 可见；在子模块中定义不会自动导出：</p><div class="language-rust line-numbers-mode" data-highlighter="shiki" data-ext="rust" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-rust"><span class="line"><span style="color:#7F848E;font-style:italic;">// main.rs（crate 根）</span></span>
<span class="line"><span style="color:#C678DD;">use</span><span style="color:#E5C07B;"> embassy_rp</span><span style="color:#ABB2BF;">::{bind_interrupts, i2c, </span><span style="color:#E5C07B;">peripherals</span><span style="color:#ABB2BF;">::</span><span style="color:#E5C07B;">I2C0</span><span style="color:#ABB2BF;">};</span></span>
<span class="line"></span>
<span class="line"><span style="color:#61AFEF;">bind_interrupts!</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">struct</span><span style="color:#E5C07B;"> Irqs</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#E5C07B;">    I2C0_IRQ</span><span style="color:#ABB2BF;"> =&gt; </span><span style="color:#E5C07B;">i2c</span><span style="color:#ABB2BF;">::</span><span style="color:#E5C07B;">InterruptHandler</span><span style="color:#ABB2BF;">&lt;</span><span style="color:#E5C07B;">I2C0</span><span style="color:#ABB2BF;">&gt;;</span></span>
<span class="line"><span style="color:#ABB2BF;">});</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">// sensor/aht20.rs 中传入 Irqs 时通过 crate::Irqs 引用</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="二、架构决策记录-adr" tabindex="-1"><a class="header-anchor" href="#二、架构决策记录-adr"><span>二、架构决策记录（ADR）</span></a></h2><h3 id="adr-1-embassy-vs-rtic-vs-bare-metal" tabindex="-1"><a class="header-anchor" href="#adr-1-embassy-vs-rtic-vs-bare-metal"><span>ADR-1：Embassy vs RTIC vs bare-metal</span></a></h3><p><strong>背景</strong>：实现 RP2040 上的周期性采集 + UART 上报，有 Embassy、RTIC、bare-metal 三个主流选择。</p><p><strong>Embassy</strong> ✅ <strong>选用</strong>：</p><ul><li><code>async/await</code> 语法与已掌握的 tokio 完全一致，认知迁移成本最低</li><li><code>#[embassy_executor::task]</code> 内置定时器集成，Timer::after_millis 无需手动配置</li><li>官方对 RP2040 有一级支持（embassy-rp crate）</li></ul><p><strong>RTIC (Real-Time Interrupt-driven Concurrency)</strong>：</p><ul><li>基于中断优先级的并发模型，没有 async/await</li><li>对有 C# async 背景的开发者心智负担较高</li><li>更适合硬实时场景（优先级调度有严格延迟保证）</li></ul><p><strong>bare-metal（main loop + 轮询）</strong>：</p><ul><li>最简单，但&quot;忙等&quot;80ms 期间 CPU 空转，无法并发其他任务</li><li>Flash 最小，但无法扩展多任务</li></ul><p><strong>结论</strong>：本项目只有一个采集任务，bare-metal 也够用，但选 Embassy 是为了掌握工程能力，为后续更复杂的多任务嵌入式系统打基础。</p><hr><h3 id="adr-2-aht20-驱动设计——借用-i2c-vs-拥有-i2c" tabindex="-1"><a class="header-anchor" href="#adr-2-aht20-驱动设计——借用-i2c-vs-拥有-i2c"><span>ADR-2：AHT20 驱动设计——借用 I²C vs 拥有 I²C</span></a></h3><p><strong>方案 A（拥有 I²C）</strong>：</p><div class="language-rust line-numbers-mode" data-highlighter="shiki" data-ext="rust" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-rust"><span class="line"><span style="color:#C678DD;">pub</span><span style="color:#C678DD;"> struct</span><span style="color:#E5C07B;"> Aht20</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#E06C75;">    i2c</span><span style="color:#ABB2BF;">: </span><span style="color:#E5C07B;">I2c</span><span style="color:#ABB2BF;">&lt;&#39;</span><span style="color:#E5C07B;">static</span><span style="color:#ABB2BF;">, </span><span style="color:#E5C07B;">I2C0</span><span style="color:#ABB2BF;">, </span><span style="color:#E5C07B;">Async</span><span style="color:#ABB2BF;">&gt;,  </span><span style="color:#7F848E;font-style:italic;">// Aht20 拥有 I²C 总线</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>问题：I²C 总线被 <code>Aht20</code> 独占，无法再挂载其他 I²C 设备（如 OLED 显示屏）。</p><p><strong>方案 B（借用 I²C）</strong> ✅ <strong>选用</strong>：</p><div class="language-rust line-numbers-mode" data-highlighter="shiki" data-ext="rust" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-rust"><span class="line"><span style="color:#C678DD;">pub</span><span style="color:#C678DD;"> struct</span><span style="color:#E5C07B;"> Aht20</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#E06C75;">    initialized</span><span style="color:#ABB2BF;">: </span><span style="color:#E5C07B;">bool</span><span style="color:#ABB2BF;">,               </span><span style="color:#7F848E;font-style:italic;">// 只存轻量状态</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">impl</span><span style="color:#E5C07B;"> Aht20</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#C678DD;">    pub</span><span style="color:#C678DD;"> async</span><span style="color:#C678DD;"> fn</span><span style="color:#61AFEF;"> read</span><span style="color:#ABB2BF;">(&amp;</span><span style="color:#C678DD;">mut</span><span style="color:#E5C07B;"> self</span><span style="color:#ABB2BF;">, </span><span style="color:#E06C75;">i2c</span><span style="color:#ABB2BF;">: &amp;</span><span style="color:#C678DD;">mut</span><span style="color:#E5C07B;"> I2c</span><span style="color:#ABB2BF;">&lt;&#39;</span><span style="color:#E5C07B;">_</span><span style="color:#ABB2BF;">, </span><span style="color:#E5C07B;">I2C0</span><span style="color:#ABB2BF;">, </span><span style="color:#E5C07B;">Async</span><span style="color:#ABB2BF;">&gt;) -&gt; </span><span style="color:#E5C07B;">Result</span><span style="color:#ABB2BF;">&lt;</span><span style="color:#E5C07B;">SensorReading</span><span style="color:#ABB2BF;">, </span><span style="color:#E5C07B;">SensorError</span><span style="color:#ABB2BF;">&gt;;</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>优点：</p><ul><li>I²C 总线在 task 中持有，驱动每次调用时借用</li><li>可以在同一个任务里同时驱动 AHT20 + 其他 I²C 设备</li><li>符合 <code>embedded-hal</code> 社区惯例</li></ul><p><strong>结论</strong>：方案 B，驱动只存必要状态（<code>initialized</code> flag），I²C handle 由调用方持有。</p><hr><h3 id="adr-3-时间戳方案——ms-since-boot-vs-utc" tabindex="-1"><a class="header-anchor" href="#adr-3-时间戳方案——ms-since-boot-vs-utc"><span>ADR-3：时间戳方案——ms since boot vs UTC</span></a></h3><p><strong>方案 A（UTC 时间）</strong>：需要 RTC 模块或 GPS，RP2040 无内置 RTC；通过 UART 从上位机同步时间，增加协议复杂度。</p><p><strong>方案 B（ms since boot）</strong> ✅ <strong>选用</strong>：</p><div class="language-rust line-numbers-mode" data-highlighter="shiki" data-ext="rust" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-rust"><span class="line"><span style="color:#C678DD;">let</span><span style="color:#E06C75;"> ts_ms</span><span style="color:#56B6C2;"> =</span><span style="color:#E5C07B;"> embassy_time</span><span style="color:#ABB2BF;">::</span><span style="color:#E5C07B;">Instant</span><span style="color:#ABB2BF;">::</span><span style="color:#61AFEF;">now</span><span style="color:#ABB2BF;">().</span><span style="color:#61AFEF;">as_millis</span><span style="color:#ABB2BF;">();</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><ul><li>零硬件依赖，<code>embassy-time</code> 提供</li><li>上位机收到后根据首条数据对齐绝对时间（加一个固定偏移量）</li><li>RP2040 Timer 精度 ±1μs，误差 &lt; 0.01%</li></ul><p><strong>结论</strong>：使用 <code>Instant::now().as_millis()</code> 作为相对时间戳，上位机负责换算 UTC。</p><hr><h3 id="adr-4-panic-处理——panic-probe-vs-panic-halt" tabindex="-1"><a class="header-anchor" href="#adr-4-panic-处理——panic-probe-vs-panic-halt"><span>ADR-4：panic 处理——<code>panic-probe</code> vs <code>panic-halt</code></span></a></h3><table><thead><tr><th></th><th><code>panic-probe</code></th><th><code>panic-halt</code></th></tr></thead><tbody><tr><td>Flash 开销</td><td>+8KB（包含文件/行号字符串）</td><td>~200 字节</td></tr><tr><td>行为</td><td>RTT 输出 panic 位置，然后断点</td><td>立即停止执行（<code>loop {}</code>）</td></tr><tr><td>适用</td><td>开发/调试阶段</td><td>生产部署</td></tr></tbody></table><p><strong>决策</strong>：Cargo feature 分开处理：</p><div class="language-toml line-numbers-mode" data-highlighter="shiki" data-ext="toml" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-toml"><span class="line"><span style="color:#7F848E;font-style:italic;"># 开发模式：cargo build（默认 dev profile）</span></span>
<span class="line"><span style="color:#E06C75;">panic-probe</span><span style="color:#ABB2BF;"> = { </span><span style="color:#E06C75;">version</span><span style="color:#ABB2BF;"> = </span><span style="color:#98C379;">&quot;0.3.2&quot;</span><span style="color:#ABB2BF;">, </span><span style="color:#E06C75;">features</span><span style="color:#ABB2BF;"> = [</span><span style="color:#98C379;">&quot;print-defmt&quot;</span><span style="color:#ABB2BF;">] }</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>生产刷机时通过 <code>Cargo.toml</code> 注释替换：<code>panic-halt = &quot;0.2&quot;</code> 节省 ~8KB Flash。</p><p>本文档的 Flash 验收（AC1）使用 <code>panic-probe</code> 测量，实际部署可切换到 <code>panic-halt</code> 进一步缩小。</p><hr><h3 id="adr-5-浮点运算策略" tabindex="-1"><a class="header-anchor" href="#adr-5-浮点运算策略"><span>ADR-5：浮点运算策略</span></a></h3><p>AHT20 原始值到温度/湿度的转换公式涉及除法（<code>/ 2^20</code>）和乘法：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>T(°C) = raw_temp / 1,048,576 × 200 - 50</span></span>
<span class="line"><span>H(%RH) = raw_hum  / 1,048,576 × 100</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>方案 A（浮点）</strong>：<code>f32</code> 计算直观，但 Cortex-M0+ 无 FPU，软件浮点库 <code>libgcc_s</code> 增加 ~8-12KB Flash。</p><p><strong>方案 B（整数 × 10，移位运算）</strong> ✅ <strong>选用</strong>：</p><div class="language-rust line-numbers-mode" data-highlighter="shiki" data-ext="rust" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-rust"><span class="line"><span style="color:#7F848E;font-style:italic;">// 2^20 = 1,048,576，用移位替代除法</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">// humidity_decipercent = (raw_hum * 1000) &gt;&gt; 20</span></span>
<span class="line"><span style="color:#C678DD;">let</span><span style="color:#E06C75;"> raw_hum</span><span style="color:#ABB2BF;">: </span><span style="color:#E5C07B;">u32</span><span style="color:#56B6C2;"> =</span><span style="color:#ABB2BF;"> ((</span><span style="color:#E06C75;">buf</span><span style="color:#ABB2BF;">[</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">] </span><span style="color:#C678DD;">as</span><span style="color:#E5C07B;"> u32</span><span style="color:#ABB2BF;">) </span><span style="color:#56B6C2;">&lt;&lt;</span><span style="color:#D19A66;"> 12</span><span style="color:#ABB2BF;">) </span><span style="color:#56B6C2;">|</span><span style="color:#ABB2BF;"> ((</span><span style="color:#E06C75;">buf</span><span style="color:#ABB2BF;">[</span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">] </span><span style="color:#C678DD;">as</span><span style="color:#E5C07B;"> u32</span><span style="color:#ABB2BF;">) </span><span style="color:#56B6C2;">&lt;&lt;</span><span style="color:#D19A66;"> 4</span><span style="color:#ABB2BF;">) </span><span style="color:#56B6C2;">|</span><span style="color:#ABB2BF;"> ((</span><span style="color:#E06C75;">buf</span><span style="color:#ABB2BF;">[</span><span style="color:#D19A66;">3</span><span style="color:#ABB2BF;">] </span><span style="color:#C678DD;">as</span><span style="color:#E5C07B;"> u32</span><span style="color:#ABB2BF;">) </span><span style="color:#56B6C2;">&gt;&gt;</span><span style="color:#D19A66;"> 4</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"><span style="color:#C678DD;">let</span><span style="color:#E06C75;"> humidity_decipercent</span><span style="color:#56B6C2;"> =</span><span style="color:#ABB2BF;"> ((</span><span style="color:#E06C75;">raw_hum</span><span style="color:#C678DD;"> as</span><span style="color:#E5C07B;"> u64</span><span style="color:#ABB2BF;"> * </span><span style="color:#D19A66;">1_000</span><span style="color:#ABB2BF;">) </span><span style="color:#56B6C2;">&gt;&gt;</span><span style="color:#D19A66;"> 20</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">as</span><span style="color:#E5C07B;"> u16</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">// temperature_decidegrees = ((raw_temp * 2000) &gt;&gt; 20) - 500</span></span>
<span class="line"><span style="color:#C678DD;">let</span><span style="color:#E06C75;"> raw_temp</span><span style="color:#ABB2BF;">: </span><span style="color:#E5C07B;">u32</span><span style="color:#56B6C2;"> =</span><span style="color:#ABB2BF;"> (((</span><span style="color:#E06C75;">buf</span><span style="color:#ABB2BF;">[</span><span style="color:#D19A66;">3</span><span style="color:#ABB2BF;">] &amp; </span><span style="color:#D19A66;">0x0F</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">as</span><span style="color:#E5C07B;"> u32</span><span style="color:#ABB2BF;">) </span><span style="color:#56B6C2;">&lt;&lt;</span><span style="color:#D19A66;"> 16</span><span style="color:#ABB2BF;">) </span><span style="color:#56B6C2;">|</span><span style="color:#ABB2BF;"> ((</span><span style="color:#E06C75;">buf</span><span style="color:#ABB2BF;">[</span><span style="color:#D19A66;">4</span><span style="color:#ABB2BF;">] </span><span style="color:#C678DD;">as</span><span style="color:#E5C07B;"> u32</span><span style="color:#ABB2BF;">) </span><span style="color:#56B6C2;">&lt;&lt;</span><span style="color:#D19A66;"> 8</span><span style="color:#ABB2BF;">) </span><span style="color:#56B6C2;">|</span><span style="color:#ABB2BF;"> (</span><span style="color:#E06C75;">buf</span><span style="color:#ABB2BF;">[</span><span style="color:#D19A66;">5</span><span style="color:#ABB2BF;">] </span><span style="color:#C678DD;">as</span><span style="color:#E5C07B;"> u32</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"><span style="color:#C678DD;">let</span><span style="color:#E06C75;"> temperature_decidegrees</span><span style="color:#56B6C2;"> =</span><span style="color:#ABB2BF;"> (((</span><span style="color:#E06C75;">raw_temp</span><span style="color:#C678DD;"> as</span><span style="color:#E5C07B;"> u64</span><span style="color:#ABB2BF;"> * </span><span style="color:#D19A66;">2_000</span><span style="color:#ABB2BF;">) </span><span style="color:#56B6C2;">&gt;&gt;</span><span style="color:#D19A66;"> 20</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">as</span><span style="color:#E5C07B;"> i32</span><span style="color:#ABB2BF;"> - </span><span style="color:#D19A66;">500</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">as</span><span style="color:#E5C07B;"> i16</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>注意 <code>raw_hum * 1000</code> 可能超过 <code>u32</code> 上限（最大 ~20 亿，乘 1000 超 u32），用 <code>u64</code> 中间算再右移。</p><p><strong>Flash 节省</strong>：无浮点运算，不链接 soft-float 库，节省约 10KB Flash。</p><hr><h2 id="三、关键实现过程" tabindex="-1"><a class="header-anchor" href="#三、关键实现过程"><span>三、关键实现过程</span></a></h2><h3 id="_3-1-first-build-——-空-embassy-main-成功" tabindex="-1"><a class="header-anchor" href="#_3-1-first-build-——-空-embassy-main-成功"><span>3.1 first build —— 空 Embassy main 成功</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#61AFEF;">$</span><span style="color:#98C379;"> cargo</span><span style="color:#98C379;"> build</span><span style="color:#D19A66;"> --release</span></span>
<span class="line"><span style="color:#61AFEF;">   Compiling</span><span style="color:#98C379;"> mo-node</span><span style="color:#98C379;"> v0.1.0</span></span>
<span class="line"><span style="color:#61AFEF;">    Finished</span><span style="color:#98C379;"> release</span><span style="color:#ABB2BF;"> [optimized] target(</span><span style="color:#61AFEF;">s</span><span style="color:#ABB2BF;">) in 18.42s</span></span>
<span class="line"></span>
<span class="line"><span style="color:#61AFEF;">$</span><span style="color:#98C379;"> cargo</span><span style="color:#98C379;"> size</span><span style="color:#D19A66;"> --release</span><span style="color:#D19A66;"> --</span><span style="color:#D19A66;"> -A</span></span>
<span class="line"><span style="color:#61AFEF;">mo-node</span><span style="color:#98C379;">  :</span></span>
<span class="line"><span style="color:#61AFEF;">section</span><span style="color:#98C379;">               size</span><span style="color:#98C379;">        addr</span></span>
<span class="line"><span style="color:#61AFEF;">.boot2</span><span style="color:#D19A66;">                 256</span><span style="color:#D19A66;">  268435456</span><span style="color:#98C379;">   ←</span><span style="color:#98C379;"> BOOT2（256</span><span style="color:#98C379;"> 字节，XIP</span><span style="color:#98C379;"> Flash</span><span style="color:#98C379;"> 前缀）</span></span>
<span class="line"><span style="color:#61AFEF;">.text</span><span style="color:#D19A66;">                18432</span><span style="color:#D19A66;">  268435712</span><span style="color:#98C379;">   ←</span><span style="color:#98C379;"> 纯</span><span style="color:#98C379;"> Embassy</span><span style="color:#98C379;"> executor</span><span style="color:#98C379;"> +</span><span style="color:#98C379;"> HAL</span><span style="color:#98C379;"> 初始化</span></span>
<span class="line"><span style="color:#61AFEF;">.rodata</span><span style="color:#D19A66;">               2048</span><span style="color:#D19A66;">  268453024</span></span>
<span class="line"><span style="color:#61AFEF;">.data</span><span style="color:#D19A66;">                    0</span><span style="color:#D19A66;">  536870912</span></span>
<span class="line"><span style="color:#61AFEF;">.bss</span><span style="color:#D19A66;">                   256</span><span style="color:#D19A66;">  536870912</span></span>
<span class="line"><span style="color:#61AFEF;">Total</span><span style="color:#D19A66;">                20992</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>空程序 ~20KB，有大量空间留给业务代码。</p><h3 id="_3-2-aht20-初始化调试" tabindex="-1"><a class="header-anchor" href="#_3-2-aht20-初始化调试"><span>3.2 AHT20 初始化调试</span></a></h3><p>初版代码在 <code>init()</code> 后立刻调用 <code>read()</code>，发现 AHT20 返回 <code>status = 0x1C</code>（Busy 位 = 0，但没有等待足够初始化时间）：</p><div class="language-rust line-numbers-mode" data-highlighter="shiki" data-ext="rust" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-rust"><span class="line"><span style="color:#7F848E;font-style:italic;">// AHT20 上电后需要 40ms 初始化时间，随后发 0xBE 初始化命令</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">// 实测：0xBE 命令发出后需要额外 10ms 校准才可读取</span></span>
<span class="line"><span style="color:#E5C07B;">Timer</span><span style="color:#ABB2BF;">::</span><span style="color:#61AFEF;">after_millis</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">40</span><span style="color:#ABB2BF;">).</span><span style="color:#C678DD;">await</span><span style="color:#ABB2BF;">;   </span><span style="color:#7F848E;font-style:italic;">// 上电等待</span></span>
<span class="line"><span style="color:#E06C75;">i2c</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">write</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">AHT20_ADDR</span><span style="color:#ABB2BF;">, &amp;</span><span style="color:#D19A66;">CMD_INIT</span><span style="color:#ABB2BF;">).</span><span style="color:#C678DD;">await</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">map_err</span><span style="color:#ABB2BF;">(</span><span style="color:#56B6C2;">|</span><span style="color:#E06C75;">_</span><span style="color:#56B6C2;">|</span><span style="color:#E5C07B;"> SensorError</span><span style="color:#ABB2BF;">::</span><span style="color:#E5C07B;">I2c</span><span style="color:#ABB2BF;">)?;</span></span>
<span class="line"><span style="color:#E5C07B;">Timer</span><span style="color:#ABB2BF;">::</span><span style="color:#61AFEF;">after_millis</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">10</span><span style="color:#ABB2BF;">).</span><span style="color:#C678DD;">await</span><span style="color:#ABB2BF;">;   </span><span style="color:#7F848E;font-style:italic;">// 初始化命令执行等待</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>通过逻辑分析仪确认时序后 defmt 日志正常。</p><h3 id="_3-3-json-格式化时负温度处理" tabindex="-1"><a class="header-anchor" href="#_3-3-json-格式化时负温度处理"><span>3.3 JSON 格式化时负温度处理</span></a></h3><p>测试时发现 <code>temperature_decidegrees = -23</code>（-2.3°C）格式化错误：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>// Bug：输出 {&quot;temp&quot;:-0.3} 而非 {&quot;temp&quot;:-2.3}</span></span>
<span class="line"><span>write!(buf, &quot;{}{}.{}&quot;, sign, t_abs / 10, t_abs % 10)</span></span>
<span class="line"><span>// t = -23, t_abs = 23 (u16), t_abs/10 = 2, t_abs%10 = 3 → 正确</span></span>
<span class="line"><span>// t = -3,  t_abs = 3  (u16), t_abs/10 = 0, t_abs%10 = 3 → &quot;-0.3&quot; ✓</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>实际上 <code>-23 / 10 = 2, -23 % 10 = 3</code> 在 Rust <code>i16</code> 中：<code>(-23i16).unsigned_abs() = 23u16</code>，<code>23 / 10 = 2, 23 % 10 = 3</code>，<strong>格式化正确</strong>。验证了所有负数分支后，逻辑无误。</p><hr><h2 id="四、工具链安装记录" tabindex="-1"><a class="header-anchor" href="#四、工具链安装记录"><span>四、工具链安装记录</span></a></h2><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 1. 添加交叉编译目标</span></span>
<span class="line"><span style="color:#61AFEF;">rustup</span><span style="color:#98C379;"> target</span><span style="color:#98C379;"> add</span><span style="color:#98C379;"> thumbv6m-none-eabi</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 2. 安装 probe-rs（烧录 + RTT 调试）</span></span>
<span class="line"><span style="color:#61AFEF;">cargo</span><span style="color:#98C379;"> install</span><span style="color:#98C379;"> probe-rs-tools</span><span style="color:#D19A66;"> --locked</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 3. 安装 cargo-size（Flash 分析）</span></span>
<span class="line"><span style="color:#61AFEF;">cargo</span><span style="color:#98C379;"> install</span><span style="color:#98C379;"> cargo-binutils</span></span>
<span class="line"><span style="color:#61AFEF;">rustup</span><span style="color:#98C379;"> component</span><span style="color:#98C379;"> add</span><span style="color:#98C379;"> llvm-tools-preview</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 4. 验证工具链</span></span>
<span class="line"><span style="color:#61AFEF;">cargo</span><span style="color:#98C379;"> build</span><span style="color:#D19A66;"> --release</span><span style="color:#ABB2BF;"> 2&gt;&amp;1 | </span><span style="color:#61AFEF;">tail</span><span style="color:#D19A66;"> -5</span></span>
<span class="line"><span style="color:#61AFEF;">cargo</span><span style="color:#98C379;"> size</span><span style="color:#D19A66;"> --release</span><span style="color:#D19A66;"> --</span><span style="color:#D19A66;"> -A</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div>`,125)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};